// The Worker's entry (wrangler.jsonc "main"): OpenNext's generated worker
// for every request, plus the daily retention job for the Cron Trigger
// (docs/onboarding-spec.md §11.6). OpenNext's documented way to add a
// handler: https://opennext.js.org/cloudflare/howtos/custom-worker.
// `scheduled` only runs from the trigger; there's no route to it.
import { neon } from "@neondatabase/serverless";
import { drizzle } from "drizzle-orm/neon-http";
// Generated by `opennextjs-cloudflare build`, so absent until a build has
// run (a clean checkout, CI's typecheck): ts-ignore, not expect-error.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { default as handler } from "./.open-next/worker.js";
import * as schema from "./db/schema";
import { runRetentionCleanup } from "./app/retentionCleanup";

interface Env {
  DATABASE_URL: string;
}

const worker = {
  fetch: handler.fetch,

  // A fresh client per run (never module scope, CLAUDE.md). The secret
  // comes from the run's own env. Awaited, not waitUntil'd: a throw fails
  // the run itself, visibly, in Workers Logs and the Cron Events list.
  async scheduled(_controller: unknown, env: Env) {
    if (!env.DATABASE_URL) throw new Error("[retention] DATABASE_URL is not set on this Worker.");
    const db = drizzle(neon(env.DATABASE_URL), { schema });
    await runRetentionCleanup(db, new Date());
  },
};

export default worker;
